  'config', COALESCE((SELECT json_object_agg(key, value) FROM rd_config), '{}'::json),
  'topics', COALESCE((SELECT json_agg(json_build_object('topic', topic, 'weight', weight) ORDER BY weight DESC) FROM rd_topics WHERE active), '[]'::json),
  'feeds', COALESCE((SELECT json_agg(json_build_object('url', url, 'kind', kind, 'category', category)) FROM rd_feeds WHERE active), '[]'::json),
  'seen', COALESCE((SELECT json_agg(url) FROM rd_seen WHERE sent_at > NOW() - make_interval(days => COALESCE((SELECT NULLIF(value,'')::int FROM rd_config WHERE key='lookback_days'), 7))), '[]'::json)
) AS payload;

