function detectMode() {
  for (const n of ['Init Webhook', 'Init Papers', 'Init Manual', 'Init News']) {
    try { if ($(n).isExecuted) return $(n).first().json.mode || 'news'; } catch (_) {}
  }
  return 'news';
}
const fs = require('fs');
const row = $input.first().json;
const payload = row.payload || row;
const mode = detectMode();
const outDir = '/files/research-digest';
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(outDir + '/.run-input.json', JSON.stringify({ mode, payload }, null, 2));
return [{ json: { mode, ready: true } }];

const item = $input.first().json;
const stdout = String(item.stdout || '').trim();
let result = {};
try {
  result = JSON.parse(stdout);
} catch (e) {
  result = { ok: false, error: 'stdout parse: ' + e.message, raw: stdout.slice(0, 800) };
}
if (!result.mode) {
  try { result.mode = $('Prepare Run').first().json.mode; } catch (_) {}
}
return [{ json: result }];

