={{ (() => {
  const items = $json.items || [];
  if (!items.length) return 'SELECT 1;';
  const esc = (s) => String(s || '').replace(/'/g, "''");
  const mode = esc($json.mode || 'news');
  const values = items.map((it) => {
    const url = esc(it.url);
    const title = esc(it.title);
    const source = esc(it.source);
    const score = Number(it.score) || 0;
    return `('${url}', '${title}', '${source}', '${mode}', ${score}, NOW(), NOW())`;
  }).join(',\n');
  return `INSERT INTO rd_seen (url, title, source, mode, score, first_seen, sent_at)\nVALUES ${values}\nON CONFLICT (url) DO UPDATE SET\n  title = EXCLUDED.title,\n  source = EXCLUDED.source,\n  mode = EXCLUDED.mode,\n  score = EXCLUDED.score,\n  sent_at = NOW();`;
})() }}
